// Break-it board: classroom plumbing. You do NOT edit this file.
//
// It watches the page and reports, for each planted attack, whether it is:
//   FIRED      the payload's JavaScript actually ran
//   LIVE       dangerous markup or data is in the page, even though it hasn't run
//              (for example, CSP stopped it, or nobody has clicked the link yet)
//   blocked    the defense is in place
//   not tried  you haven't triggered that feature yet
//
// The payloads call window.__breakit('<id>') so a successful attack is visible
// here and in the console. Every "attack" is local and benign.

const ROWS = [
  { id: "url-banner",        part: 2, label: "Welcome banner from ?welcome= in the URL", how: "Use the \"Try the URL payload\" link below." },
  { id: "event-title",       part: 2, label: "Event title from the API",                 how: "Sign in. The list loads." },
  { id: "event-link",        part: 2, label: "Event link: javascript: URL",              how: "Sign in. Look at the \"Free Pizza Night\" link." },
  { id: "event-description", part: 2, label: "Event description (rich HTML)",           how: "Sign in. The list loads." },
  { id: "preview",           part: 2, label: "Post-an-event preview (your input)",      how: "Type a payload, then click Preview." },
  { id: "featured-html",     part: 3, label: "Featured: hostile non-JSON response",     how: "Click \"Load featured\"." },
  { id: "token-exposure",    part: 3, label: "Session token readable or sent in a URL",  how: "Sign in." },
  { id: "smuggled-field",    part: 4, label: "Event details: smuggled canEdit field",   how: "Click Details on the pottery event." },
  { id: "proto-pollution",   part: 4, label: "Imported filters pollute Object.prototype", how: "Paste a __proto__ payload, then click Import." },
];

const fired = new Set();
const tried = new Set();
const prototypeBaseline = new Set(Object.getOwnPropertyNames(Object.prototype));
const csp = { header: "checking…", enforced: 0, reportOnly: 0, last: "" };

window.__breakit = function (id) {
  fired.add(id);
  console.error(`[break-it] "${id}" payload EXECUTED`);
  refresh();
};

// ---- detection helpers -----------------------------------------------------
const URL_ATTRS = new Set(["href", "src", "action", "formaction", "xlink:href"]);

function hasDangerousMarkup(root) {
  if (!root) return false;
  for (const el of root.querySelectorAll("*")) {
    if (el.tagName === "SCRIPT" || el.tagName === "IFRAME" || el.tagName === "OBJECT") return true;
    for (const a of el.attributes) {
      if (/^on/i.test(a.name)) return true;
      if (URL_ATTRS.has(a.name.toLowerCase()) && /^\s*javascript:/i.test(a.value)) return true;
    }
  }
  return false;
}

// Is a payload carrying this marker sitting in an ATTRIBUTE anywhere?
// (As plain text it is harmless, so text nodes don't count.)
function markerInAttributes(id) {
  const needle = `__breakit('${id}')`;
  for (const el of document.body.querySelectorAll("*")) {
    for (const a of el.attributes) if (a.value.includes(needle)) return true;
  }
  return false;
}

function isVisible(el) {
  return !!el && !el.hidden && el.getClientRects().length > 0;
}

function storageHoldsToken() {
  for (const store of [window.localStorage, window.sessionStorage]) {
    for (let i = 0; i < store.length; i++) {
      const v = store.getItem(store.key(i)) || "";
      if (/nb_[0-9a-f]{8,}/.test(v)) return "token is readable in Web Storage";
    }
  }
  const leaked = performance.getEntriesByType("resource").some((e) => /[?&]access_token=/.test(e.name));
  if (leaked) return "token was sent in a URL (see the server log)";
  return "";
}

function pollutedKeys() {
  return Object.getOwnPropertyNames(Object.prototype).filter((k) => !prototypeBaseline.has(k));
}

// ---- per-row evaluation ----------------------------------------------------
function evaluate(id) {
  const list = document.getElementById("event-list");
  const listLoaded = !!list && list.children.length > 0;

  switch (id) {
    case "url-banner": {
      if (!new URLSearchParams(location.search).has("welcome")) return ["waiting"];
      return hasDangerousMarkup(document.getElementById("welcome-banner")) ? ["live", "markup is in the banner"] : ["blocked"];
    }
    case "event-title":
    case "event-description":
      if (!listLoaded) return ["waiting"];
      return markerInAttributes(id) ? ["live", "payload is in the DOM as real markup"] : ["blocked"];
    case "event-link":
      if (!listLoaded) return ["waiting"];
      return markerInAttributes(id) ? ["live", "a javascript: link is on the page. Click it."] : ["blocked"];
    case "preview": {
      const pv = document.getElementById("preview");
      if (!pv || !pv.hasChildNodes()) return ["waiting"];
      return hasDangerousMarkup(pv) ? ["live", "dangerous markup in the preview"] : ["blocked"];
    }
    case "featured-html":
      if (!tried.has(id)) return ["waiting"];
      return hasDangerousMarkup(document.getElementById("featured")) ? ["live", "raw HTML response was rendered"] : ["blocked"];
    case "token-exposure": {
      const why = storageHoldsToken();
      if (why) return ["live", why];
      return isVisible(document.getElementById("user-greeting")) ? ["blocked"] : ["waiting"];
    }
    case "smuggled-field":
      if (isVisible(document.getElementById("edit-event"))) return ["live", "the \"Edit this event\" button appeared"];
      return tried.has(id) ? ["blocked"] : ["waiting"];
    case "proto-pollution": {
      const keys = pollutedKeys();
      if (keys.length) return ["live", "Object.prototype gained: " + keys.join(", ")];
      return tried.has(id) ? ["blocked"] : ["waiting"];
    }
  }
  return ["waiting"];
}

const LABEL = { fired: "FIRED", live: "LIVE", blocked: "blocked", waiting: "not tried" };

// ---- rendering -------------------------------------------------------------
let cells = {};
let cspLine;

function build() {
  const host = document.getElementById("breakit");
  if (!host) return;

  cspLine = document.createElement("p");
  cspLine.className = "csp-line";
  host.append(cspLine);

  const table = document.createElement("table");
  const head = table.createTHead().insertRow();
  for (const h of ["Attack", "Part", "Status"]) {
    const th = document.createElement("th");
    th.scope = "col";
    th.textContent = h;
    head.append(th);
  }
  const body = table.createTBody();
  for (const row of ROWS) {
    const tr = body.insertRow();
    tr.dataset.vector = row.id;
    const name = tr.insertCell();
    const strong = document.createElement("span");
    strong.className = "attack-name";
    strong.textContent = row.label;
    const how = document.createElement("span");
    how.className = "attack-how";
    how.textContent = row.how;
    name.append(strong, how);
    tr.insertCell().textContent = String(row.part);
    const status = tr.insertCell();
    status.className = "bk-status";
    cells[row.id] = status;
  }
  host.append(table);

  const tryUrl = document.createElement("a");
  tryUrl.className = "try-link";
  tryUrl.href = "/?welcome=" + encodeURIComponent(`<img src=x onerror="__breakit('url-banner')">`);
  tryUrl.textContent = "Try the URL payload (?welcome=…)";
  host.append(tryUrl);
}

// An attack that worked once worked. It stays flagged until the page reloads.
const seen = new Map();

function refresh() {
  for (const row of ROWS) {
    const cell = cells[row.id];
    if (!cell) continue;
    let [state, detail] = evaluate(row.id);
    if (fired.has(row.id)) { state = "fired"; detail = "the payload's JavaScript RAN"; }
    if (state === "fired" || state === "live") seen.set(row.id, [state, detail]);
    else if (seen.has(row.id)) [state, detail] = [seen.get(row.id)[0], seen.get(row.id)[1] + " (earlier on this page load)"];
    cell.dataset.state = state;
    cell.textContent = LABEL[state] + (detail ? ": " + detail : "");
  }
  if (cspLine) {
    cspLine.textContent =
      `CSP header: ${csp.header}. Violations this page load: ${csp.enforced} blocked, ${csp.reportOnly} report-only` +
      (csp.last ? ` (last: ${csp.last})` : "");
  }
}

// Mark features as "tried" when their buttons are used (capture phase, so it
// runs no matter how app.js wires its own listeners).
document.addEventListener("click", (e) => {
  const t = e.target instanceof Element ? e.target : null;
  if (!t) return;
  if (t.closest("#featured-btn")) tried.add("featured-html");
  if (t.closest("#import-filters-btn")) tried.add("proto-pollution");
  if (t.closest('#event-list button[data-event-id="4"]')) tried.add("smuggled-field");
  setTimeout(refresh, 300);
}, true);

document.addEventListener("securitypolicyviolation", (e) => {
  if (e.disposition === "report") csp.reportOnly++; else csp.enforced++;
  const file = (e.sourceFile || "").split("/").pop();
  csp.last = `${e.effectiveDirective} blocked ${e.blockedURI || "inline"}${file ? " in " + file : ""}`;
  refresh();
});

async function readOwnPolicy() {
  try {
    const res = await fetch(location.pathname, { method: "HEAD", cache: "no-store" });
    const enforced = res.headers.get("content-security-policy");
    const reportOnly = res.headers.get("content-security-policy-report-only");
    csp.header = enforced ? "ENFORCED" : reportOnly ? "REPORT-ONLY" : "none";
    if (enforced && reportOnly) csp.header = "ENFORCED (+ report-only draft)";
  } catch {
    csp.header = "unknown";
  }
  refresh();
}

build();
readOwnPolicy();
refresh();
setInterval(refresh, 500);
